// ../src/server/notifications/email.ts
async function sendEmail(apiKey, input) {
  const to = Array.isArray(input.to) ? input.to : [input.to];
  try {
    const fromEmail = input.from || process.env.RESEND_FROM_EMAIL || "Signatis <reports@signatis.app>";
    const body = {
      from: fromEmail,
      to,
      subject: input.subject,
      html: input.html
    };
    if (input.replyTo) {
      body.reply_to = input.replyTo;
    }
    if (input.attachment) {
      body.attachments = [
        {
          filename: input.attachment.filename,
          content: input.attachment.content,
          content_type: input.attachment.contentType ?? "application/pdf"
        }
      ];
    }
    const response = await fetch(`${RESEND_API_BASE}/emails`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(body)
    });
    const data = await response.json();
    if (!response.ok) {
      const errorData = data;
      const errorMsg = errorData?.message ?? errorData?.error ?? `HTTP ${response.status}`;
      console.error("[Email] Send failed:", errorMsg);
      return { success: false, error: String(errorMsg) };
    }
    const successData = data;
    return {
      success: true,
      id: successData?.id
    };
  } catch (err) {
    const message2 = err instanceof Error ? err.message : "Unknown error";
    console.error("[Email] Exception:", message2);
    return { success: false, error: message2 };
  }
}
